def PublishedNotificationReferencesExistingCluster():
    for mid in msg_status:
        if msg_status[mid] == "PUBLISHED":
            cid = msg_cluster[mid]
            if cid not in cluster_status:
                return False
    return True


# check: every PUBLISHED notification references a topic that exists

def PublishedNotificationReferencesExistingTopic():
    for mid in msg_status:
        if msg_status[mid] == "PUBLISHED":
            tid = msg_topic[mid]
            if tid not in topic_status:
                return False
    return True
